# make_samples.py - saves 2 test images per class (86 PNGs) to samples/ for the hand-in,
# so the teacher can run: python test.py --checkpoint <model>.pt --samples samples
# Source note: adapted from code generated by Claude (Anthropic), Nov 2026.

import os
from data import load_gtsrb

ds = load_gtsrb()["test"]                       # only the clean test split is needed
os.makedirs("samples", exist_ok=True)
n = {}                                          # how many images have been saved per class so far
for i, y in enumerate(ds["label"]):
    if n.get(y, 0) < 2:                         # keep the first 2 images of each class
        # File name holds the true class, e.g. class07_1.png ({y:02d} writes 7 as 07 so files sort in order)
        ds[i]["image"].save(f"samples/class{y:02d}_{n.get(y, 0)}.png")
        n[y] = n.get(y, 0) + 1
